\label{thm:glueing_weak_approx}
    Consider a recollement of singly compactly generated triangulated categories:
    \begin{displaymath}
        \begin{tikzcd}[column sep=6em]
            {\mathcal{D}_Z} & {\mathcal{D}} & {\mathcal{D}_U.}
            \arrow["{i_\ast}" description, from=1-1, to=1-2]
            \arrow["{i^\ast}"', bend right=35, from=1-2, to=1-1]
            \arrow["{i^!}", bend left=35, from=1-2, to=1-1]
            \arrow["{j^\ast}" description, from=1-2, to=1-3]
            \arrow["{j_!}"', bend right=35, from=1-3, to=1-2]
            \arrow["{j_\ast}", bend left=35, from=1-3, to=1-2]
        \end{tikzcd}
    \end{displaymath}
    Assume that $\mathcal{D}_Z$ and $\mathcal{D}_U$ are weakly approximable. Suppose $G^\prime$ is a compact generator of $\mathcal{D}$.
    Then $\mathcal{D}$ is weakly approximable if, and only if, $\operatorname{Hom}(G^\prime,G^\prime[n])=0$ for $n\gg 0$.

\label{def:weak_approx}
    A triangulated category $\mathcal{T}$ is \textbf{weakly approximable} if there exist a compact generator $G$, a $t$-structure $(\mathcal{T}^{\leq 0},\mathcal{T}^{\geq 0})$ and an integer $A>0$ such that:
    \begin{enumerate}
        \item \label{def:weak_approx1} $G\in \mathcal{T}^{\leq A}$ and $\operatorname{Hom}(G,\mathcal{T}^{\leq -A})=0$;
        \item \label{def:weak_approx2} every $F\in \mathcal{T}^{\leq 0}$ admits a distinguished triangle $E\to F\to D\to E[1]$ with $E\in \overline{\langle G\rangle}^{[-A,A]}$ and $D\in \mathcal{T}^{\leq -1}$.
    \end{enumerate}
    We call $(G,\mathcal{T}^{\leq 0},A)$ \textbf{weak approximation data}.

First we prove \textcolor{darkblue}{(\ref{lem:closures1})}.
    By definition, $\overline{\langle H\rangle}^{[a,b]} := \operatorname{smd}(\operatorname{Coprod}(H[a,b]))$. 
    Let $\Lambda$ be a set.
    Choose $X_\lambda \in \overline{\langle H\rangle}^{[a,b]}$ where $\lambda \in \Lambda$. 
    For each $\lambda \in \Lambda$, there exists $X^\prime_\lambda \in \mathcal{T}$ such that $X_\lambda \oplus X^\prime_\lambda\in \operatorname{Coprod}(H[a,b])$.
    Since $\operatorname{Coprod}(H[a,b])$ is closed under small coproducts, $\oplus_{\lambda\in \Lambda} (X_\lambda \oplus X^\prime_\lambda)\in \operatorname{Coprod}(H[a,b])$. 
    Note that $\oplus_{\lambda\in \Lambda}X_\lambda$ is a direct summand of $\oplus_{\lambda\in \Lambda} (X_\lambda \oplus X^\prime_\lambda)$. 
    Hence, $\overline{\langle H\rangle}^{[a,b]}$ is closed under small coproducts. 

    Consider a distinguished triangle 
    \begin{displaymath}
        A \to B \to C \to A[1]
    \end{displaymath}
    where $A,C\in \overline{\langle H\rangle}^{[a,b]}$. 
    We can find $A^\prime,C^\prime$ such that $A\oplus A^\prime, C\oplus C^\prime \in \operatorname{Coprod}(H[a,b])$. 
    There exist distinguished triangles
    \begin{displaymath}
        A^\prime \xrightarrow{1_{A^\prime}} A^\prime \to 0 \to A^\prime[1]
    \end{displaymath}
    and \begin{displaymath}
        0 \to C^\prime \xrightarrow{1_{C^\prime}} C^\prime \to 0[1].
    \end{displaymath}
    Taking the direct sum of these distinguished triangles yields a distinguished triangle 
    \begin{displaymath}
        \begin{aligned}
            A\bigoplus A^\prime \bigoplus 0 
            \to B \bigoplus A^\prime \bigoplus C^\prime
            \to C \bigoplus 0 \bigoplus C^\prime \to A[1]\bigoplus A^\prime[1] \bigoplus 0.
        \end{aligned}
    \end{displaymath}
    See \cite[Proposition 1.2.1]{Neeman:2001}. 
    Since $A\oplus A^\prime, C\oplus C^\prime\in  \operatorname{Coprod}(H[a,b])$, it follows that $B \oplus A^\prime \oplus C^\prime\in \operatorname{Coprod}(H[a,b])$ because the category is closed under extensions.
    Consequently, $B \in \overline{\langle H\rangle}^{[a,b]}$.

    To see that $\overline{\langle H\rangle}^{[a,b]}$ is closed under direct summands, use the fact that a direct summand of a direct summand remains a direct summand.

    Lastly, we show the minimality claim. 
    Let $\mathcal{B}$ be a strictly full subcategory of $\mathcal{T}$ closed under small coproducts, extensions, and direct summands that contains $H[a,b]$.
    In this case, $\operatorname{Coprod}(H[a,b])\subseteq \mathcal{B}$. 
    Indeed, $\mathcal{B}$ is closed under small coproducts and extensions, and it contains $H[a,b]$. 
    Moreover, $\operatorname{smd}(\operatorname{Coprod}(H[a,b]))\subseteq \mathcal{B}$ because $\mathcal{B}$ is closed under direct summands. 

    Second we prove \textcolor{darkblue}{(\ref{lem:closures2})}. 
    The autoequivalence $[s]\colon \mathcal{T} \to \mathcal{T}$ preserves extensions, small coproducts, and direct summands. 
    Hence, $\overline{\langle H\rangle}^{[a,b]}[s]$ is the smallest strictly full subcategory containing $(H[a,b])[s]$ which is closed under extensions, small coproducts, and direct summands.
    However, shifting by $s$ yields 
    \begin{displaymath}
        \begin{aligned}
            (H[a,b])[s] 
            &= \{ H [-k][s] : a\leq k \leq b \} 
            \\&= \{ H [-k+s] : a\leq k \leq b \}
            \\&=\{ H [-l] : a-s\leq l \leq b-s \}
            \\&=: H[a-s,b-s].
        \end{aligned}
    \end{displaymath}
    It follows that $\overline{\langle H\rangle}^{[a,b]}[s] = \overline{\langle H\rangle}^{[a-s,b-s]}$. 
    Moreover, as $H[a,b]\subseteq H[a^\prime,b^\prime]$, \textcolor{darkblue}{(\ref{lem:closures1})} implies $\overline{\langle H\rangle}^{[a,b]} \subseteq \overline{\langle H\rangle}^{[a^\prime,b^\prime]}$.

    Third we prove \textcolor{darkblue}{(\ref{lem:closures3})}.
    Choose $a\leq k\leq b$.
    Note that $F$ is exact and $F(H)\in \overline{\langle H^\prime\rangle}^{[c,d]}$.
    Hence, by \textcolor{darkblue}{(\ref{lem:closures2})},
    \begin{displaymath}
        F(H[-k])\cong F(H)[-k]
        \in \overline{\langle H^\prime\rangle}^{[c,d]}[-k] 
        = \overline{\langle H^\prime\rangle}^{[c+k,d+k]}\subseteq \overline{\langle H^\prime\rangle}^{[a+c,b+d]}.
    \end{displaymath}
    Set $\mathcal{S}$ to be the full subcategory of $E\in \mathcal{T}$ such that $F(E)\in \overline{\langle H^\prime\rangle}^{[a+c,b+d]}$.
    It follows that $H[a,b]\subseteq \mathcal{S}$.
    By \textcolor{darkblue}{(\ref{lem:closures1})}, $\overline{\langle H^\prime\rangle}^{[a+c,b+d]}$ is strictly full and closed under small coproducts, extensions, and direct summands.
    Since $F$ preserves small coproducts, $\mathcal{S}$ has the same properties.
    By minimality, \textcolor{darkblue}{(\ref{lem:closures1})} implies $\overline{\langle H\rangle}^{[a,b]}\subseteq \mathcal{S}$.
    Thus, \textcolor{darkblue}{(\ref{lem:closures3})} follows.

    Next we prove \textcolor{darkblue}{(\ref{lem:closures4})}. 
    It is easy to see that $\{E : \operatorname{Hom}(E,Y)=0\}$ is strictly full. 
    Let $\Lambda$ be a set. 
    Choose $X_\lambda \in \{E : \operatorname{Hom}(E,Y)=0\}$.
    By the universal property of coproducts, there exists an isomorphism
    \begin{displaymath}
        \operatorname{Hom}(\bigoplus_{\lambda \in \Lambda} X_\lambda, Y) 
        \cong \prod_{\lambda \in \Lambda} \operatorname{Hom}(X_\lambda, Y)
        \cong 0.
    \end{displaymath} 
    See \cite[Example 1.1.13]{Neeman:2001} applied to $\mathcal{T}^{op}$. 
    The last isomorphism follows from the fact that each $X_\lambda \in \{E : \operatorname{Hom}(E,Y)=0\}$.
    Hence, $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under small coproducts. 
    Let $A,B\in \{E : \operatorname{Hom}(E,Y)=0\}$.
    Consider an extension $C$ given by a distinguished triangle 
    \begin{displaymath}
        A \to C \to B \to A[1].
    \end{displaymath}
    Apply $\operatorname{Hom}(-,Y)$ to obtain a long exact sequence in Hom sets 
    \begin{displaymath}
        \cdots \to \operatorname{Hom}(B,Y) \to \operatorname{Hom}(C,Y) \to \operatorname{Hom}(A,Y) \to \cdots.
    \end{displaymath}
    Hence, $\operatorname{Hom}(C,Y) \cong 0$ if 
    \begin{displaymath}
        \operatorname{Hom}(A,Y) \cong \operatorname{Hom}(B,Y) \cong 0.
    \end{displaymath}
    This implies $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under extensions.
    Moreover, if $A\oplus B \in \{E : \operatorname{Hom}(E,Y)=0\}$, then 
    \begin{displaymath}
        \operatorname{Hom}(A\oplus B,Y)\cong \operatorname{Hom}(A,Y) \bigoplus \operatorname{Hom}(B,Y) \cong 0.
    \end{displaymath} 
    Thus, $\{E : \operatorname{Hom}(E,Y)=0\}$ is closed under direct summands. 
    The hypothesis asserts that $H[a,b]\subseteq \{E : \operatorname{Hom}(E,Y)=0\}$.
    By \textcolor{darkblue}{(\ref{lem:closures1})}, $\overline{\langle H \rangle}^{[a,b]}\subseteq \{E : \operatorname{Hom}(E,Y)=0\}$.
    A similar argument with $H$ compact proves the second claim for \textcolor{darkblue}{(\ref{lem:closures4})}.
    Indeed, the compactness of $H$ gives the closure under coproducts, whereas the other conditions are analogous.

    Lastly we prove \textcolor{darkblue}{(\ref{lem:closures5})}. 
    Let $X\in \operatorname{smd}(\operatorname{Coprod}(H[a,b]))$.
    Choose $X^\prime$ such that $X\oplus X^\prime \in \operatorname{Coprod}(H[a,b])$.
    The so-called Eilenberg swindle yields an isomorphism
    \begin{displaymath}
        \begin{aligned}
            X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) 
            &\cong X \oplus (\bigoplus_{n\in \mathbb{N}} (X^\prime \oplus X)) 
            \\&\cong X \oplus (X^\prime \oplus X) \oplus (X^\prime \oplus X) \oplus \cdots
            \\&\cong (X \oplus X^\prime) \oplus (X \oplus X^\prime) \oplus \cdots
            \\&\cong \bigoplus_{n\in \mathbb{N}} (X \oplus X^\prime).
        \end{aligned}
    \end{displaymath}
    Consequently, there exists a distinguished triangle 
    \begin{displaymath}
        X \to X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) \to \bigoplus_{n\in \mathbb{N}}(X\oplus X^\prime) \to X[1].
    \end{displaymath}

    Rotating backwards yields 
    \begin{displaymath}
        (\bigoplus_{n\in \mathbb{N}}( X\oplus X^\prime))[-1] 
        \to X \to X \oplus (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime)) \to \bigoplus_{n\in \mathbb{N}}( X\oplus X^\prime).
    \end{displaymath}
    Since $[a,b]\subseteq [a,b+1]$, $\operatorname{Coprod}(H[a,b]) \subseteq \operatorname{Coprod}(H[a,b+1])$.
    Observe that 
    \begin{displaymath}
        \begin{aligned}
            (\bigoplus_{n\in \mathbb{N}} (X\oplus X^\prime))[-1]
            &\in \operatorname{Coprod}(H[a,b])[-1] 
            \\&= \operatorname{Coprod}(H[a+1,b+ 1])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]).
        \end{aligned}
    \end{displaymath}
    Therefore, 
    \begin{displaymath}
        \begin{aligned}
            X 
            &\in \operatorname{Coprod}(H[a,b+1]) \star \operatorname{Coprod}(H[a,b])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]) \star \operatorname{Coprod}(H[a,b+1])
            \\&\subseteq \operatorname{Coprod}(H[a,b+1]).
        \end{aligned}
    \end{displaymath}
    This completes the proof.

\label{rmk:octahedral}
    We use the octahedral axiom in the following ways.
    Let $X\xrightarrow{f} Y\xrightarrow{g} Z$ be composable.
    \begin{enumerate}
        \item \label{rmk:octahedraloc} Choose distinguished triangles $X\xrightarrow{f} Y\to C_f\to X[1]$, $Y\xrightarrow{g} Z\xrightarrow{p_g} C_g\to Y[1]$ and $X\xrightarrow{gf} Z\xrightarrow{p_{gf}} C_{gf}\to X[1]$. There is a distinguished triangle $C_f\to C_{gf}\xrightarrow{h} C_g\to C_f[1]$ with $h\circ p_{gf} = p_g$. See e.g.\ \cite[Proposition 1.4.6]{Neeman:2001}.
        \item \label{rmk:octahedralof} Choose distinguished triangles $F_f\to X\xrightarrow{f} Y\to F_f[1]$, $F_g\to Y\xrightarrow{g} Z\to F_g[1]$ and $F_{gf}\to X\xrightarrow{gf} Z\to F_{gf}[1]$. There is a distinguished triangle $F_f\to F_{gf}\to F_g\to F_f[1]$. Indeed, take the distinguished triangle $C_f\to C_{gf}\xrightarrow{h} C_g\to C_f[1]$ and shift by $[-1]$. Here we use that $F_? \cong C_?[-1]$.
    \end{enumerate}

\label{lem:aisle}
    Let $(\mathcal{T}^{\leq 0},\mathcal{T}^{\geq 0})$ be a $t$-structure on a triangulated category $\mathcal{T}$.
    Consider a distinguished triangle  
    \begin{displaymath}
        E\to F\to D\to E[1]
    \end{displaymath}
    where $F\in \mathcal{T}^{\leq 0}$ and $D\in \mathcal{T}^{\leq -m}$ for some $m\geq 1$.
    Then $E\in \mathcal{T}^{\leq 0}$.

By rotating backwards, there exists a distinguished triangle  
    \begin{displaymath}
       D[-1] \to E\to F\to D.
    \end{displaymath}
    Note that $D[-1]\in \mathcal{T}^{\leq 1-m} \subseteq \mathcal{T}^{\leq 0}$.
    Since aisles are closed under extensions, $E\in \mathcal{T}^{\leq 0}$.

\label{lem:iterate}
    Let $(H,\mathcal{T}^{\leq 0},A)$ be weak approximation data for $\mathcal{T}$.
    For every $F\in \mathcal{T}^{\leq 0}$ and every $m\geq 1$, there exists a distinguished triangle 
    \begin{displaymath}
        E_m\to F\to D_m\to E_m[1]
    \end{displaymath}
    with $E_m\in \overline{\langle H\rangle}^{[1-m-A,A]} \cap \mathcal{T}^{\leq 0}$ and $D_m\in \mathcal{T}^{\leq -m}$.

This follows from \cite[Corollary 3.2(1)]{Neeman:2026} with weak approximation data for $\mathcal{T}$.
    To be self-contained, we give a proof.
    By \Cref{lem:aisle}, for any desired distinguished triangle 
    \begin{displaymath}
        E_m\to F\to D_m\to E_m[1],
    \end{displaymath}
    it follows that $E_m\in \mathcal{T}^{\leq 0}$.
    Hence, it suffices to produce the desired distinguished triangle.
    We argue by induction on $m$. 
    The base case $m=1$ is \Cref{def:weak_approx}\textcolor{darkblue}{(\ref{def:weak_approx2})}.

    Assume that the desired distinguished triangle exists for $m$, i.e.\ a distinguished triangle 
    \begin{displaymath}
        E_m\to F\xrightarrow{f} D_m\to E_m[1]
    \end{displaymath}
    with $E_m\in \overline{\langle H\rangle}^{[1-m-A,A]} \cap \mathcal{T}^{\leq 0}$ and $D_m\in \mathcal{T}^{\leq -m}$. 
    Since $D_m[-m]\in \mathcal{T}^{\leq 0}$, \Cref{def:weak_approx}\textcolor{darkblue}{(\ref{def:weak_approx2})} yields a distinguished triangle 
    \begin{displaymath}
        E^\prime \to D_m[-m]\to D^\prime \to E^\prime[1]
    \end{displaymath}
    where $E^\prime \in \overline{\langle H\rangle}^{[-A,A]}$ and $D^\prime \in \mathcal{T}^{\leq -1}$.

    After shifting by $[m]$, we have a distinguished triangle 
    \begin{displaymath}
        E^\prime[m]\to D_m\xrightarrow{g} D^\prime[m]\to E^\prime[m+1]
    \end{displaymath}
    where $E^\prime[m]\in \overline{\langle H\rangle}^{[-A-m,A-m]}$ and $D^\prime[m]\in \mathcal{T}^{\leq -1-m}$.
    Set $D_{m+1} := D^\prime[m]$. 
    Complete the composite $g\circ f \colon F\to D^\prime[m]$ to a distinguished triangle,
    \begin{displaymath}
        F\to D^\prime[m] \to R \to F[1].
    \end{displaymath}
    Set $E_{m+1}:=R[-1]$. 
    The cocones of $f$, $g$, and $g\circ f$ are respectively $E_m$, $E^\prime[m]$, and $E_{m+1}$. 
    By \Cref{rmk:octahedral}\textcolor{darkblue}{(\ref{rmk:octahedralof})}, this yields a distinguished triangle 
    \begin{displaymath}
        E_m \to E_{m+1} \to E^\prime [m] \to E_m [1].
    \end{displaymath}
    By \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures1})}\textcolor{darkblue}{(\ref{lem:closures2})},
    \begin{displaymath}
        \begin{aligned}
            E_{m+1} 
            & \in \overline{\langle H\rangle}^{[1-m-A,A]} \star \overline{\langle H\rangle}^{[-m-A,A-m]}
            \\& \subseteq \overline{\langle  H\rangle}^{[-m-A,A]} 
            \\&= \overline{\langle H\rangle}^{[1-(m+1)-A,A]}.
        \end{aligned}
    \end{displaymath}
    This completes the proof.

This is \cite[Remark 1.24]{Neeman:2026}; cf.\ \cite[Lemma 3.5(1)]{Burke/Neeman/Pauwels:2023}.
    On one hand, 
    \begin{displaymath}
        \begin{aligned}
            \mathcal{T}^{\leq -n_0} 
            &= \mathcal{T}^{\leq 0}[n_0] 
            \\&= \operatorname{Coprod}(\{H[n] : n\geq n_0\}).
        \end{aligned}
    \end{displaymath}
    On the other hand, the strictly full subcategory 
    \begin{displaymath}
        \{Y \in \mathcal{T} : \operatorname{Hom}(H,Y)=0\}
    \end{displaymath}
    contains $H[n]$ for $n\geq n_0$. 
    Moreover, by \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures4})}, this subcategory above is closed under small coproducts and extensions.
    Consequently, the subcategory above contains $\mathcal{T}^{\leq -n_0}$.
    Thus, the desired claim follows.

\label{setup:recollement}
    Consider a recollement of singly compactly generated triangulated categories: 
    \begin{displaymath}
        \begin{tikzcd}[column sep=6em]
            {\mathcal{D}_Z} & {\mathcal{D}} & {\mathcal{D}_U.}
            \arrow["{i_\ast}" description, from=1-1, to=1-2]
            \arrow["{i^\ast}"', bend right=35, from=1-2, to=1-1]
            \arrow["{i^!}", bend left=35, from=1-2, to=1-1]
            \arrow["{j^\ast}" description, from=1-2, to=1-3]
            \arrow["{j_!}"', bend right=35, from=1-3, to=1-2]
            \arrow["{j_\ast}", bend left=35, from=1-3, to=1-2]
        \end{tikzcd}
    \end{displaymath}
    For every $E\in \mathcal{D}$, there are distinguished triangles
    \begin{equation}
        \label{eq:gluing_triangles}
        \begin{aligned}
            j_! j^\ast E 
            & \xrightarrow{\epsilon_E} E 
            \xrightarrow{\eta_E} i_\ast i^\ast E 
            \xrightarrow{\varphi_E} j_! j^\ast E[1],
            \\& i_\ast i^! E \to E \to j_\ast j^\ast E \to i_\ast i^! E[1].
        \end{aligned}
    \end{equation}
    Here $\epsilon$ is the counit of $j_! \dashv j^\ast$ and $\eta$ is the unit of $i^\ast \dashv i_\ast$.

\label{setup:standing}
    Consider \Cref{setup:recollement}.
    Assume that $\mathcal{D}_Z$ and $\mathcal{D}_U$ are weakly approximable.
    Suppose $\mathcal{D}$ has a compact generator $G^\prime$ satisfying $\operatorname{Hom}(G^\prime,G^\prime[n])=0$ for $n\gg 0$.
    Fix a compact generator $G_U$ of $\mathcal{D}_U$.
    Choose $m$ and $G = G^\prime[m]\oplus j_! G_U$ from \Cref{lem:normalize}.
    Consider the following $t$-structures:
    \begin{itemize}
        \item $\mathcal{D}_U^{\leq 0}$ is compactly generated by $G_U$;
        \item $\mathcal{D}_Z^{\leq 0}$ is compactly generated by $i^\ast G$;
        \item $\mathcal{D}^{\leq 0}$ is the glued $t$-structure (by \Cref{lem:normalize}\textcolor{darkblue}{(\ref{lem:normalize3})}, it is the $t$-structure compactly generated by $G$; hence, $G\in \mathcal{D}^{\leq 0}$).
    \end{itemize}
    Note that $\mathcal{D}_U^{\leq 0}$ and $\mathcal{D}_Z^{\leq 0}$ are respectively in the preferred equivalence classes of $\mathcal{D}_U$ and $\mathcal{D}_Z$. 
    By \cite[Lemma 3.7]{Burke/Neeman/Pauwels:2023} (equivalently, \cite[Proposition 3.6]{Neeman:2026}), \Cref{lem:hom_vanishing}, and \Cref{lem:normalize}\textcolor{darkblue}{(\ref{lem:normalize4})}, there exist $A_1,A_2,A_3 \gg 0$ such that the following hold:
    \begin{enumerate}
        \item \label{setup:standinga1} $(i^\ast G,\mathcal{D}_Z^{\leq 0},A_1)$ is weak approximation data for $\mathcal{D}_Z$
        \item \label{setup:standinga2} $(G_U,\mathcal{D}_U^{\leq 0},A_2)$ is weak approximation data for $\mathcal{D}_U$
        \item \label{setup:standinga3} $\operatorname{Hom}(G,\mathcal{D}^{\leq -A_3})=0$.
    \end{enumerate}
    Set $A= \max\{A_1,A_2,A_3\}$. 
    Define $K := A+1$, $B := 3A$, and $\mathcal{P} := \overline{\langle G\rangle}^{[-B,B]} \cap \mathcal{D}^{\leq K}$.
    By \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures1})}, and the fact that aisles are closed under extensions and small coproducts, $\mathcal{P}$ is closed under small coproducts and extensions.
    Since $j_! G_U$ is a direct summand of $G$, it follows that $j_! G_U\in \overline{\langle G\rangle}^{[0,0]}$.

The following proof is a variant of \cite[Lemma 5.3]{Burke/Neeman/Pauwels:2023}.
    Specifically, the lift is constructed directly from the adjunct $g$ rather than from a roof \cite[Lemma 5.2]{Burke/Neeman/Pauwels:2023}, and it lies in $\mathcal{D}^{\leq K}$ for the same $K$ that bounds $Y$.

    Since $i^\ast$ is exact, $i^\ast(G[n])$ can be identified with $(i^\ast G)[n]$.
    Hence, $f^\prime$ yields a morphism $i^\ast(G[n])\to i^\ast Y$.
    Denote by $\eta$ the unit and $\overline{\varepsilon}$ the counit of $i^\ast\dashv i_\ast$.

    Set $M := j^\ast Y$.
    By \Cref{lem:glued}, $M\in \mathcal{D}_U^{\leq K}$, and so $M[K]\in \mathcal{D}_U^{\leq 0}$.
    Apply \Cref{lem:iterate} to the weak approximation data $(G_U,\mathcal{D}_U^{\leq 0},A)$ of \Cref{setup:standing}\textcolor{darkblue}{(\ref{setup:standinga2})}, $M[K]$, and $3A+1 = K+2A$ in place of $m$.
    This gives a distinguished triangle
    \begin{displaymath}
        W^\prime\to M[K]\to V^\prime\to W^\prime[1].
    \end{displaymath}
    Here $W^\prime\in \overline{\langle G_U\rangle}^{[-4A,A]}\cap \mathcal{D}_U^{\leq 0}$ and $V^\prime\in \mathcal{D}_U^{\leq -3A-1}$.
    Define $W := W^\prime[-K]$ and $V := V^\prime[-K]$.
    Shifting by $[-K]$ yields a distinguished triangle
    \begin{equation}
        \label{eq:onecell_wc}
        W\xrightarrow{w} M\xrightarrow{c} V\to W[1].
    \end{equation}
    By \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures2})},
    \begin{displaymath}
        W\in \overline{\langle G_U\rangle}^{[-4A+K,A+K]} = \overline{\langle G_U\rangle}^{[1-3A,2A+1]}.
    \end{displaymath}
    Moreover, $W\in \mathcal{D}_U^{\leq 0}[-K] = \mathcal{D}_U^{\leq K}$ and $V\in \mathcal{D}_U^{\leq -3A-1}[-K] = \mathcal{D}_U^{\leq -2A}$.

    Now let $g\colon G[n]\to i_\ast i^\ast Y$ be the adjunct of $f^\prime$.
    That is, $g = i_\ast(f^\prime)\circ \eta_{G[n]}$, and so $f^\prime = \overline{\varepsilon}_{i^\ast Y}\circ i^\ast(g)$.
    Set
    \begin{displaymath}
        \varphi := \varphi_Y\colon i_\ast i^\ast Y\to j_! M[1]
    \end{displaymath}
    to be the morphism in \textcolor{darkblue}{(\ref{eq:gluing_triangles})}, and $\xi := \varphi\circ g$. 
    By \Cref{lem:glued}, $j_! V\in \mathcal{D}^{\leq -2A}$.
    As $n\leq A$, 
    \begin{displaymath}
        j_! V[1-n]\in \mathcal{D}^{\leq n-1-2A}\subseteq \mathcal{D}^{\leq -A}.
    \end{displaymath}
    Hence, \Cref{setup:standing}\textcolor{darkblue}{(\ref{setup:standinga3})} gives
    \begin{equation}
        \label{eq:onecell_vanishing}
        \operatorname{Hom}(G[n],j_! V[1])\cong \operatorname{Hom}(G,j_! V[1-n]) = 0.
    \end{equation}
    Applying $j_!$ to \textcolor{darkblue}{(\ref{eq:onecell_wc})} gives a distinguished triangle
    \begin{displaymath}
        j_! W\xrightarrow{j_!(w)} j_! M \xrightarrow{j_!(c)} j_! V\to j_! W[1].
    \end{displaymath}
    By \cite[Lemma 1.1.10]{Neeman:2001}, $\operatorname{Hom}(G[n-1],-)$ is a homological functor on $\mathcal{D}$.
    This yields an exact sequence
    \begin{displaymath}
        \operatorname{Hom}(G[n-1],j_! W)
        \xrightarrow{j_!(w)\circ -} \operatorname{Hom}(G[n-1],j_! M)
        \xrightarrow{j_!(c)\circ -} \operatorname{Hom}(G[n-1],j_! V).
    \end{displaymath}
    By \textcolor{darkblue}{(\ref{eq:onecell_vanishing})}, 
    \begin{displaymath}
        \operatorname{Hom}(G[n-1],j_! V)\cong \operatorname{Hom}(G[n],j_! V[1]) = 0.
    \end{displaymath}
    Hence, the left-hand map is surjective.
    Thus, there exists $\xi^{\prime\prime}\colon G[n-1]\to j_! W$ such that $\xi[-1] = j_!(w)\circ \xi^{\prime\prime}$.
    Setting $\xi^\prime := \xi^{\prime\prime}[1]\colon G[n]\to j_! W[1]$, we get $\xi = j_!(w)[1]\circ \xi^\prime$.

    Next we construct the lift.
    Completing $\xi^\prime$ and rotating backwards twice yields a distinguished triangle
    \begin{equation}
        \label{eq:onecell_triangle}
        j_! W\xrightarrow{\alpha} Q\xrightarrow{\beta} G[n]\xrightarrow{\xi^\prime} j_! W[1].
    \end{equation}

    Consider the diagram
    \begin{displaymath}
        \begin{tikzcd}
            j_! W \ar[r, "\alpha"] \ar[d, "j_!(w)"'] & Q \ar[r, "\beta"] \ar[d, dashed, "q"] & G[n] \ar[r, "\xi^\prime"] \ar[d, "g"] & j_! W[1] \ar[d, "{j_!(w)[1]}"] \\
            j_! M \ar[r, "\epsilon_Y"] & Y \ar[r, "\eta_Y"] & i_\ast i^\ast Y \ar[r, "\varphi"] & j_! M [1]
        \end{tikzcd}
    \end{displaymath}
    with distinguished rows.
    Indeed, the top row is \textcolor{darkblue}{(\ref{eq:onecell_triangle})}, whereas the bottom row is the first triangle of \textcolor{darkblue}{(\ref{eq:gluing_triangles})} for $E = Y$ (i.e.\ use that $M = j^\ast Y$).
    The right-hand square commutes because 
    \begin{displaymath}
        \varphi\circ g = \xi = j_!(w)[1]\circ \xi^\prime.
    \end{displaymath}
    By TR3, applied after rotating both rows backwards, there exists $q\colon Q\to Y$ making the diagram commute.
    In particular, $\eta_Y\circ q = g\circ \beta$.

    Set $\theta := i^\ast\beta\colon i^\ast Q\to i^\ast(G[n]) = (i^\ast G)[n]$.
    Recall that $i^\ast$ is exact and $i^\ast j_! = 0$.
    Applying $i^\ast$ to \textcolor{darkblue}{(\ref{eq:onecell_triangle})} gives a distinguished triangle
    \begin{displaymath}
        0\to i^\ast Q\xrightarrow{\theta} i^\ast(G[n])\to 0[1],
    \end{displaymath}
    and so $\theta$ is an isomorphism.
    Moreover, applying $i^\ast$ to $\eta_Y\circ q = g\circ \beta$ and using the triangle identity $\overline{\varepsilon}_{i^\ast Y}\circ i^\ast(\eta_Y) = 1_{i^\ast Y}$, it follows that
    \begin{displaymath}
        i^\ast q
        = \overline{\varepsilon}_{i^\ast Y}\circ i^\ast(\eta_Y)\circ i^\ast q
        = \overline{\varepsilon}_{i^\ast Y}\circ i^\ast(g)\circ i^\ast\beta
        = f^\prime\circ \theta.
    \end{displaymath}

    Lastly, we check that $Q$ lies in $\mathcal{P}$.
    By \textcolor{darkblue}{(\ref{eq:onecell_triangle})}, $Q\in j_! W\star G[n]$.
    Since $\mathcal{P}$ is closed under extensions, it suffices to show that $j_! W, G[n]\in \mathcal{P}$.
    The functor $j_!$ is exact, preserves small coproducts, and satisfies $j_! G_U\in \overline{\langle G\rangle}^{[0,0]}$ by \Cref{setup:standing}.
    By \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures3})}, $j_! W\in \overline{\langle G\rangle}^{[1-3A,2A+1]}$.
    As $A\geq 1$, we have $2A+1\leq 3A = B$, so \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures2})} gives $j_! W\in \overline{\langle G\rangle}^{[-B,B]}$.
    Moreover, by \Cref{lem:glued}, $W\in \mathcal{D}_U^{\leq K}$ implies $j_! W\in \mathcal{D}^{\leq K}$.
    Since $-A-1\leq n\leq A$, one has $-A\leq -n\leq A+1$, and so $G[n] = G[-(-n)]\in G[-A,A+1]$.
    Applying \Cref{lem:closures}\textcolor{darkblue}{(\ref{lem:closures2})} with $A+1\leq 3A$, $G[n]\in \overline{\langle G\rangle}^{[-A,A+1]}\subseteq \overline{\langle G\rangle}^{[-B,B]}$.
    As $G\in \mathcal{D}^{\leq 0}$ by \Cref{setup:standing}, $G[n]\in \mathcal{D}^{\leq -n}\subseteq \mathcal{D}^{\leq A+1} = \mathcal{D}^{\leq K}$.
    Thus, $Q\in \mathcal{P}$, and so $(q,\theta)$ is a $\mathcal{P}$-lift of $f^\prime$.

\label{prop:closure}
    Assume \Cref{setup:standing}. 
    The subcategory $\mathcal{C}$ is strictly full, closed under small coproducts and extensions, and contains $(i^\ast G)[n]$ for $-A-1\leq n\leq A$.
    Consequently,
    \begin{displaymath}
        \overline{\langle i^\ast G\rangle}^{[-A,A]}\subseteq \operatorname{Coprod}((i^\ast G)[-A,A+1])\subseteq \mathcal{C}.
    \end{displaymath}

\label{prop:A8}
    Consider an elementary distinguished square $j\colon U\to X$ and $f\colon Y\to X$ of quasi-compact quasi-separated algebraic spaces (see \cite[\href{https://stacks.math.columbia.edu/tag/08GM}{Tag 08GM}]{StacksProject}). 
    If $U$ and $Y$ satisfy W.A., then so does $X$.

\label{rmk:stacks_version}
    With one additional lemma on finite flat covers, the argument of \Cref{cor:weak_approx_spaces} adapts to tame algebraic stacks.
    We do not pursue this.
